* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; font-size: 16px; color: #25333d; background: #e8f0e8; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background-color: #e8f0e8; background-image: linear-gradient(45deg, #dce8df 25%, transparent 25%), linear-gradient(-45deg, #dce8df 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #dce8df 75%), linear-gradient(-45deg, transparent 75%, #dce8df 75%); background-size: 28px 28px; background-position: 0 0, 0 14px, 14px -14px, -14px 0; }
.panel { width: min(100%, 520px); padding: clamp(22px, 6vw, 40px); background: #fffdf5; border: 3px solid #25333d; box-shadow: 8px 8px 0 #25333d; }
.header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #547c70; font-size: .8rem; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.5rem); line-height: 1.15; letter-spacing: -.04em; }
.subtitle { margin: 10px 0 24px; color: #62717a; }
.count-card { display: flex; align-items: center; justify-content: center; gap: 10px; padding: 14px; background: #dcefe5; border: 2px solid #25333d; font-size: 1.1rem; }
.count-card strong { font-size: 1.5rem; }
.count-icon { color: #547c70; font-size: 1.6rem; }
.alarm-form { margin-top: 24px; }
fieldset { min-width: 0; margin: 0; padding: 18px; border: 2px solid #cbd9d0; }
legend { padding: 0 8px; font-weight: 750; }
.time-fields { display: flex; align-items: end; gap: 12px; }
.time-fields label, .label-field { display: grid; gap: 6px; font-weight: 650; }
.time-fields label { flex: 1; }
.time-fields input { text-align: center; }
input { width: 100%; min-height: 48px; padding: 10px 12px; border: 2px solid #aabbb2; border-radius: 0; background: white; color: #25333d; font: inherit; }
input:focus-visible, button:focus-visible { outline: 3px solid #d18a36; outline-offset: 3px; }
.time-colon { padding-bottom: 10px; font-size: 1.4rem; font-weight: 800; }
.label-field { margin-top: 14px; }
.optional { color: #6e7b7c; font-weight: 400; }
.add-button { width: 100%; min-height: 50px; margin-top: 16px; border: 2px solid #25333d; background: #547c70; color: white; font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s, background .12s; }
button:hover { background: #42695d; }
button:active { transform: translateY(2px); }
.list-section { margin-top: 28px; }
.list-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
h2 { margin: 0 0 12px; font-size: 1.2rem; }
.sort-note { color: #6e7b7c; font-size: .9rem; }
.alarm-list { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
.alarm-row { display: flex; align-items: center; gap: 12px; min-width: 0; padding: 12px; border: 2px solid #d0dad3; background: #fff; }
.alarm-row.is-off { opacity: .62; }
.alarm-time { min-width: 88px; font-size: 1.35rem; font-weight: 800; font-variant-numeric: tabular-nums; }
.alarm-label { flex: 1; min-width: 0; overflow-wrap: anywhere; color: #586970; }
.toggle-control { display: flex; align-items: center; gap: 7px; font-size: .9rem; cursor: pointer; }
.toggle-control input { width: 22px; min-height: 22px; height: 22px; margin: 0; accent-color: #547c70; cursor: pointer; }
.delete-button { min-width: 42px; min-height: 42px; border: 2px solid #c7795e; background: #fff5ef; color: #743f31; font: inherit; font-weight: 700; cursor: pointer; }
.delete-button:hover { background: #f4ded2; }
.empty-state { margin: 0; padding: 20px 12px; border: 2px dashed #cbd9d0; color: #62717a; text-align: center; }
footer { margin-top: 28px; color: #6e7b7c; font-size: .75rem; font-weight: 750; letter-spacing: .12em; text-align: center; }
footer span { color: #d18a36; }
@media (max-width: 400px) { body { padding: 20px 12px; } .panel { padding: 22px 18px; box-shadow: 5px 5px 0 #25333d; } .alarm-row { gap: 8px; padding: 9px; } .alarm-time { min-width: 76px; font-size: 1.2rem; } .toggle-control { gap: 4px; } .sort-note { font-size: .82rem; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const list = document.querySelector('#alarm-list');
const count = document.querySelector('#enabled-count');
const emptyState = document.querySelector('#empty-state');
let alarms = [];
let nextId = 1;

function render() {
  alarms.sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute) || a.id - b.id);
  list.replaceChildren();
  let enabled = 0;

  for (const alarm of alarms) {
    if (alarm.enabled) enabled += 1;
    const item = document.createElement('li');
    item.className = `alarm-row${alarm.enabled ? '' : ' is-off'}`;
    const time = document.createElement('span');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    const label = document.createElement('span');
    label.className = 'alarm-label';
    label.textContent = alarm.label || 'Alarm';
    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'toggle-control';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = alarm.enabled;
    toggle.setAttribute('aria-label', `Alarm ${time.textContent} ${alarm.label || ''} on`);
    toggle.addEventListener('change', () => {
      alarm.enabled = toggle.checked;
      render();
    });
    toggleLabel.append(toggle, document.createTextNode('On'));
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = 'Delete';
    remove.setAttribute('aria-label', `Delete alarm at ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(entry => entry.id !== alarm.id);
      render();
    });
    item.append(time, label, toggleLabel, remove);
    list.append(item);
  }

  count.textContent = String(enabled);
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return;
  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  form.reset();
  hourInput.focus();
  render();
});

render();
